 $('#workflowContent').innerHTML=`<div class="dialog-head"><div><p class="eyebrow">ДОКУМЕНТ ${i+1} ИЗ ${draft.sections.length}</p><h2>${esc(s.name||'Документ проверки')}</h2><p class="muted">Запишите замечания по выбранному документу. После сохранения вернётесь к списку.</p></div><button type="button" class="icon-btn" id="closeIdDocument" aria-label="К списку документов">×</button></div><div class="workflow-body"><label class="field full"><span>Название документа</span><input id="sectionName" value="${esc(s.name||'')}"></label><div class="field-grid"><div class="field"><span>Номер документа</span><label class="switch"><input id="sectionNumberEnabled" type="checkbox" ${s.numberEnabled||rules.required?'checked':''} ${s.numberRequired||rules.required?'disabled':''}><span></span><b>Указывать номер</b></label></div><label class="field"><span>Дата документа</span><input id="sectionDate" type="date" value="${esc(s.date||'')}"></label></div><label class="field full ${s.numberEnabled||rules.required?'':'hidden'}" id="sectionNumberWrap"><span>№ документа ${s.numberRequired||rules.required?'· обязательно':''}</span><input id="sectionNumber" value="${esc(s.number||'')}" placeholder="Например: АОСР-303-17" ${s.numberRequired||rules.required?'required':''}></label><label class="switch section-enabled"><input id="sectionEnabled" type="checkbox" ${s.enabled===false?'':'checked'}><span></span><b>Включить документ в итоговую проверку</b></label><div class="remarks-head"><h3>Замечания · ${remarks.length}</h3><button type="button" class="secondary-btn" id="newRemark">＋ Добавить замечание</button></div><div class="remark-list">${remarks.map((m,j)=>`<article class="manual-remark"><div class="manual-remark-copy"><strong>${j+1}.</strong><p>${esc(m.text)}</p></div><label class="switch" title="Включить замечание в итоговый документ"><input type="checkbox" data-remark-toggle="${j}" ${m.enabled===false?'':'checked'}><span></span></label><div class="registry-actions"><button type="button" data-edit-remark="${j}">Изменить</button><button type="button" class="registry-remove" data-delete-remark="${j}">Удалить</button></div></article>`).join('')||'<p class="hint">Замечаний пока нет. Нажмите «Добавить замечание», чтобы внести текст вручную.</p>'}</div>${showRemark?`<div class="remark-editor"><label class="field full"><span>Текст замечания</span><textarea id="manualRemarkText" placeholder="Введите замечание по этому документу">${esc(editIndex>=0?remarks[editIndex]?.text||'':'')}</textarea></label><div><button type="button" class="secondary-btn" id="cancelRemark">Отмена</button><button type="button" class="primary-btn" id="saveRemark">Сохранить</button></div></div>`:''}</div><div class="dialog-actions"><button type="button" class="secondary-btn" id="sectionCancel">К списку документов</button><span class="spacer"></span><button type="button" class="primary-btn" id="sectionDone">Сохранить и вернуться к списку</button></div>`;
 const root=$('#workflowContent'),returnToList=()=>{$('#workflowDialog').close();paintEditor(draft)};
