 $('#sectionNumberEnabled').onchange=()=>{const old=s.number;saveSectionFields();s.numberEnabled=$('#sectionNumberEnabled').checked||s.numberRequired;s.number=old;paintEditor(draft);renderSection(i,showRemark,editIndex)};
