 $('#cancelRemark')?.addEventListener('click',()=>renderSection(i));
 $('#saveRemark')?.addEventListener('click',async()=>{const text=$('#manualRemarkText').value.trim();if(!text){toast('Введите текст замечания');$('#manualRemarkText').focus();return}if(!saveSectionFields())return;if(editIndex>=0)remarks[editIndex].text=text;else remarks.push({id:uid(),text,enabled:true});const saved=await persistCard(false);if(saved){$('#workflowDialog').close();paintEditor(draft);toast('Замечание сохранено')}});
 root.querySelectorAll('[data-remark-toggle]').forEach(b=>b.onchange=()=>{if(!saveSectionFields())return;remarks[+b.dataset.remarkToggle].enabled=b.checked;paintEditor(draft);renderSection(i)});
 root.querySelectorAll('[data-edit-remark]').forEach(b=>b.onclick=()=>{if(saveSectionFields()){paintEditor(draft);renderSection(i,true,+b.dataset.editRemark)}});
 root.querySelectorAll('[data-delete-remark]').forEach(b=>b.onclick=()=>{if(!saveSectionFields())return;const j=+b.dataset.deleteRemark;if(confirm('Удалить замечание?')){remarks.splice(j,1);paintEditor(draft);renderSection(i)}})
