function saveSectionFields(){const s=draft.sections[sectionIndex],name=$('#sectionName').value.trim(),rules=numberRules(name);if(!name){toast('Укажите название раздела');return false}s.name=name;s.numberRequired=rules.required;s.numberEnabled=s.numberRequired||$('#sectionNumberEnabled').checked;s.number=s.numberEnabled?$('#sectionNumber').value.trim():'';s.date=$('#sectionDate').value;s.enabled=$('#sectionEnabled').checked;return true}

